import{_ as n,o,c as t,ai as e}from"./chunks/framework.Ai2o9gNv.js";const s="/assets/AtomCode%E5%BE%AE%E4%BF%A1%E5%B0%8F%E7%A8%8B%E5%BA%8F%E5%85%A8%E6%B5%81%E7%A8%8B%E6%80%BB%E8%A7%88.CWP957js.svg",r="/assets/image-20260609111825689.c3ri5lHx.png",i="/assets/image-20260609111842302.7abv7kUV.png",m="/assets/image-20260609113733740.B_rvyi_l.png",p="/assets/image-20260609113752860.BlvQLSGY.png",c="/assets/image-20260609141737676.Dqq0SLa1.png",d="/assets/%E5%BE%AE%E4%BF%A1%E5%B0%8F%E7%A8%8B%E5%BA%8F%E5%88%9B%E5%BB%BA%E5%8F%91%E5%B8%83%E6%B5%81%E7%A8%8B%E6%80%BB%E8%A7%88.B56vPQFa.svg",l="/assets/image-20260609142743406.cbG-Ox-K.png",h="/assets/image-20260609142800890.zNPkZncg.png",g="/assets/image-20260609144009348.BGkFy_92.png",_="/assets/image-20260609142847397.C4pNQxT8.png",q="/assets/image-20260609142924773.Dg3VRtKm.png",b="/assets/image-20260609142953818.3iwr5RbV.png",u="/assets/image-20260609144138459.Dzeiq7Ig.png",A="/assets/image-20260609144734434.RE0Eq2i-.png",k="/assets/image-20260609145421268.buz2ra0M.png",D=JSON.parse('{"title":"AtomCode开发微信小程序《谁去呀》 全流程","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/AtomcCode开发微信小程序全流程/AtomcCode开发微信小程序全流程.md","filePath":"AI人工智能/AtomcCode开发微信小程序全流程/AtomcCode开发微信小程序全流程.md","lastUpdated":1781048308000,"__rawMarkdown":"# AtomCode开发微信小程序《谁去呀》 全流程\\n\\n\\n\\n## 流程总览\\n\\n![AtomCode 开发微信小程序全流程总览图](./AtomCode微信小程序全流程总览.svg)\\n\\n\\n\\n\\n\\n## 什么是AtomCode\\n\\n> https://atomcode.atomgit.com/\\n\\n![](assets/image-20260609111825689.png)\\n\\n\\n\\n## 下载安装AtomCode\\n\\n![](assets/image-20260609111842302.png)\\n\\n\\n\\n安装成功后，终端中输入命令，查看版本信息\\n\\n> atomcode --version\\n\\n## AtomCode简单使用\\n\\n### 首次使用\\n\\n首次使用，需要在终端中输入  `atomcode`\\n\\n---\\n\\n**选择语言**\\n\\n![](assets/image-20260609113733740.png)\\n\\n---\\n\\n\\n\\n**选择验证方式**\\n\\n![](assets/image-20260609113752860.png)\\n\\n\\n\\n### 使用技巧\\n\\n在每一个新的工程中，首次执行，都建议 执行一次 `/init` ，这个命令是让atomcode熟悉你的工程，同时也可以把一些项目开发到的约定填写进去，这个文件可以随着项目的进行来更新和维护。\\n\\n后续你可以使用自然语言和atomcode对话来实现你的功能需求；\\n\\n> https://atomcode.atomgit.com/docs/zh/slash-commands.html\\n\\n![](assets/image-20260609141737676.png)\\n\\n## 微信小程序创建-发布流程总览\\n\\n![微信小程序创建到发布流程总览图](./微信小程序创建发布流程总览.svg)\\n\\n\\n\\n## 注册微信小程序开发者账号\\n\\n> https://mp.weixin.qq.com/\\n\\n![](assets/image-20260609142743406.png)\\n\\n---\\n\\n\\n\\n![](assets/image-20260609142800890.png)\\n\\n## \\n\\n\\n\\n## 获取微信小程序的APPID\\n\\nAPPID用来开发和发布使用，成功小程序后台便可以轻松获取。\\n\\n在**管理-开发管理-开发设置**中可以获取小程序的**APPID**\\n\\n![](assets/image-20260609144009348.png)\\n\\n这个id先记住，稍后使用。\\n\\n\\n\\n\\n\\n## 下载微信开发者工具\\n\\n> https://developers.weixin.qq.com/miniprogram/dev/devtools/devtools.html\\n\\n![](assets/image-20260609142847397.png)\\n\\n\\n\\n---\\n\\n下载成功\\n\\n![](assets/image-20260609142924773.png)\\n\\n\\n\\n## 新建微信小程序工程\\n\\n打开微信开发者工具，然后新建项目。\\n\\n\\n\\n![](assets/image-20260609142953818.png)\\n\\n\\n\\n考虑后端的能力，可以选择云开发-最低20元一个月。\\n\\n也可以不选择云开发，如果自己有后端的话，**万少这里是使用自己的后端能力。**\\n\\n这里可以填写上面保存好的**AppID**。\\n\\n![](assets/image-20260609144138459.png)\\n\\n---\\n\\n万少这里是将 小程序和后端放在同一个目录内，方便**atomcode**操作。\\n\\n![](assets/image-20260609144734434.png)\\n\\n## 生成产品原型图\\n\\n考虑到具体要开发的产品，最好是先生成产品的原型图，然后以它作为参考，使用**atomcode**辅助开发小程序端和后端。\\n\\n![](assets/image-20260609145421268.png)\\n\\n\\n\\n## 协同开发客户端和后端\\n\\n这里的开发顺序可以是：\\n\\n1. **优先开发大部分小程序端的功能，包括页面设计、基本交互等，如果涉及和后端交互的数据，可以让atomcode在小程序端先使用模拟数据。**\\n2. **待小程序端开发差不多后，可以进行后端功能开发。**\\n3. **然后过程中，前端和后端协同开发即可。**\\n\\n\\n\\n这里罗列部分提示词，可以用来做参考\\n\\n\\n\\n### 初始化工程\\n\\n> goOrNot 是微信小程序端工程，goOrNot-backend 是后端工程，帮我使用init 命令进行初始化\\n\\n\\n\\n\\n\\n\\n\\n## 真机预览和真机调试\\n\\n\\n\\n## 发布上线全流程\\n\\n\\n\\n## 结尾\\n\\n\\n\\n"}'),P={name:"AI人工智能/AtomcCode开发微信小程序全流程/AtomcCode开发微信小程序全流程.md"};function f(x,a,E,B,C,v){return o(),t("div",null,[...a[0]||(a[0]=[e("",65)])])}const w=n(P,[["render",f]]);export{D as __pageData,w as default};
